FOR UPDATE

SELECT MAX(inbound_date)

FROM inbound

WHERE company_id = #{companyId}
AND purchase_order_id = #{purchaseOrderId}
AND status = 'CONFIRMED'

SELECT COUNT(*)

FROM inbound

WHERE company_id = #{companyId}
AND purchase_order_id = #{purchaseOrderId}
AND status = 'DRAFT'

SELECT l.lot_id, l.company_id, l.product_id, l.lot_no, l.manufacture_date, l.expiry_date
FROM lot l
WHERE l.company_id = #{companyId} AND l.product_id = #{productId} AND l.lot_no = #{lotNo}

mapper.delete:
DELETE FROM inbound_item

WHERE inbound_id = #{inboundId}

AND EXISTS
(
SELECT 1

FROM inbound i

WHERE i.inbound_id = #{inboundId}
AND i.company_id = #{companyId}
AND i.status = 'DRAFT'
)

mapper.update:
UPDATE purchase_order_item

SET received_qty =
received_qty + #{baseReceivedQty}

WHERE purchase_order_item_id = #{purchaseOrderItemId}
AND purchase_order_id = #{purchaseOrderId}
AND received_qty + #{baseReceivedQty}
<= base_ordered_qty

AND EXISTS
(
SELECT 1

FROM purchase_order po

WHERE po.purchase_order_id = #{purchaseOrderId}
AND po.company_id = #{companyId}
AND po.approval_status = 'APPROVED'
AND po.receipt_status IN ('NOT_RECEIVED', 'PARTIAL')
)

UPDATE inbound

SET status = 'CONFIRMED',
confirmed_by = #{confirmedBy},
confirmed_at =
CAST(
SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul'
AS TIMESTAMP
)

WHERE inbound_id = #{inboundId}
AND company_id = #{companyId}
AND purchase_order_id = #{purchaseOrderId}
AND status = 'DRAFT'

UPDATE lot_stock

SET quantity =
quantity + #{baseLotQty}

WHERE company_id = #{companyId}
AND warehouse_id = #{warehouseId}
AND lot_id = #{lotId}

AND EXISTS
(
SELECT 1

FROM lot l

WHERE l.lot_id = lot_stock.lot_id
AND l.company_id = #{companyId}
AND l.product_id = #{productId}
)

mapper.insert:
